/**
 * VoiceBill v3.0.3 — Production-Hardened Voice GST Invoicing & Payment Management SaaS
 *  - Smart Parser v5.1 (Quoted Multi-Sentence GST Quotes, Full Verb Stripping, Zero ₹0 Residue)
 *  - Encrypted Private GitHub Gist Cloud Persistence (Accounts & 30-day Sessions Survive Redeploys)
 *  - Pro Solo ₹299 / 30 days
 */
const fs = require('fs');
const path = require('path');

const FILES = {
  "src/finance.js": "",
  "src/parser.js": "",
  "src/store.js": "",
  "src/server.js": "",
  "public/finance.js": "",
  "public/index.html": "",
  "public/portal.html": "",
  "public/styles.css": "",
  "public/app.js": "",
  "public/manifest.json": "",
  "public/sw.js": ""
};

for (const [relPath, b64] of Object.entries(FILES)) {
  const fullPath = path.join(__dirname, relPath);
  fs.mkdirSync(path.dirname(fullPath), { recursive: true });
  fs.writeFileSync(fullPath, Buffer.from(b64, 'base64'));
}

console.log('[VoiceBill v3.0.3] Unpacked ' + Object.keys(FILES).length + ' verified modules.');
const { createApp, initCloudPersistence } = require('./src/server.js');
const PORT = process.env.PORT || 3000;

initCloudPersistence()
  .then((res) => {
    if (res && res.restored) {
      console.log('[VoiceBill Cloud Sync] Restored ' + res.usersRestored + ' account(s) from encrypted cloud backup.');
    }
  })
  .catch(() => {})
  .finally(() => {
    createApp().listen(PORT, '0.0.0.0', () => {
      console.log('VoiceBill v3.0.3 SaaS listening on http://0.0.0.0:' + PORT);
    });
  });
